import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ----------------------------------------------------------------------
# CUDA source implementing half‑precision matrix‑vector multiplication
# ----------------------------------------------------------------------
cuda_source = r'''
#include <torch/extension.h>
#include <cuda_fp16.h>
#include <cuda_runtime.h>

__global__ void matvec_fp16_kernel(const half* __restrict__ A,
                                   const half* __restrict__ B,
                                   half* __restrict__ C,
                                   int M, int K) {
    int row = blockIdx.x * blockDim.x + threadIdx.x;
    if (row >= M) return;

    float acc = 0.0f;
    const half* a_row = A + row * K;

    // Simple unrolled loop for better throughput
    for (int k = 0; k < K; ++k) {
        acc += __half2float(a_row[k]) * __half2float(B[k]);
    }
    C[row] = __float2half(acc);
}

void matvec_fp16_launcher(at::Tensor A, at::Tensor B, at::Tensor C) {
    const int M = A.size(0);
    const int K = A.size(1);

    const dim3 block(256);
    const dim3 grid((M + block.x - 1) / block.x);

    const half* A_ptr = reinterpret_cast<const half*>(A.data_ptr<at::Half>());
    const half* B_ptr = reinterpret_cast<const half*>(B.data_ptr<at::Half>());
    half* C_ptr = reinterpret_cast<half*>(C.data_ptr<at::Half>());

    matvec_fp16_kernel<<<grid, block>>>(A_ptr, B_ptr, C_ptr, M, K);
    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        AT_ERROR("CUDA kernel launch failed: ", cudaGetErrorString(err));
    }
}
'''

# ----------------------------------------------------------------------
# Compile the inline extension
# ----------------------------------------------------------------------
matvec_ext = load_inline(
    name='matvec_fp16_ext',
    cpp_sources='',
    cuda_sources=cuda_source,
    functions=['matvec_fp16_launcher'],
    verbose=False,
)

# ----------------------------------------------------------------------
# PyTorch model that uses the custom kernel
# ----------------------------------------------------------------------
class ModelNew(nn.Module):
    """
    Drop‑in replacement for the reference Model.
    Performs C = A @ B where A is (M, K) and B is (K, 1), all in fp16.
    """
    def __init__(self):
        super().__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        # Ensure correct dtype and device
        if A.dtype != torch.float16:
            A = A.half()
        if B.dtype != torch.float16:
            B = B.half()
        assert A.is_cuda and B.is_cuda, "Inputs must be CUDA tensors"
        M, K = A.shape
        assert B.shape == (K, 1), f"B must have shape ({K},1), got {B.shape}"
        # Output tensor
        C = torch.empty((M, 1), dtype=torch.float16, device=A.device)
        # Launch kernel (B is contiguous as (K,1); view as (K,) works automatically)
        matvec_ext.matvec_fp16_launcher(A, B, C)
